/**
 * "Ask for a feedback" button of the student step pages (formative feedback, v2.11.4).
 *
 * The copy shown is saved first (Autosave.save()), then the feedback is asked for, then the page reloads.
 *
 * @module     mod_gestionprojet/formative_button
 * @copyright  2026 Emmanuel REMY
 * @license    http://www.gnu.org/copyleft/gpl.html GNU GPL v3 or later
 */
define(["core/ajax","core/notification","mod_gestionprojet/autosave"],(function(t,e,n){"use strict";return{init:function(o){var i=document.getElementById(o.buttonId);i&&i.addEventListener("click",(function(){i.disabled=!0;var r=n.save();Promise.resolve(r).catch((function(){return null})).then((function(){return t.call([{methodname:"mod_gestionprojet_request_formative",args:{cmid:o.cmid,step:o.step,groupid:o.groupid}}])[0]})).then((function(){var t=new URL(window.location.href);return t.searchParams.set("_",String(Date.now())),window.location.href=t.toString(),null})).catch((function(t){i.disabled=!1,e.exception(t)}))}))}}}));